// Evidence-based investment ideas built from valuation, momentum and macro context.
(() => {
  'use strict';

  let screenerPromise = null;
  let quoteCachePromise = null;
  let loadSeq = 0;
  let tagObserver = null;

  const esc = (v) => String(v ?? '')
    .replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;').replaceAll("'", '&#39;');
  const asNum = (v) => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v))) ? null : Number(v);
  const num = (v, d = 1) => asNum(v) === null ? '-' : asNum(v).toFixed(d);
  const pct = (v) => asNum(v) === null ? '-' : `${asNum(v) > 0 ? '+' : ''}${asNum(v).toFixed(1)}%`;

  function selected() {
    if (typeof perTickers !== 'undefined' && Array.isArray(perTickers)) return [...perTickers];
    if (typeof selectedTickers !== 'undefined' && Array.isArray(selectedTickers)) return [...selectedTickers];
    return ['AAPL', 'NVDA'];
  }

  function installTab() {
    const nav = document.querySelector('.tab-nav');
    if (!nav || nav.querySelector('[data-tab="ideas"]')) return;

    const btn = document.createElement('button');
    btn.className = 'tab-btn';
    btn.dataset.tab = 'ideas';
    btn.textContent = '💡 투자 아이디어';
    const valuation = nav.querySelector('[data-tab="fwdper"]');
    if (valuation) valuation.insertAdjacentElement('afterend', btn); else nav.appendChild(btn);

    const tab = document.createElement('div');
    tab.id = 'ideas-tab';
    tab.className = 'tab-content';
    tab.innerHTML = `
      <section class="ideas-section">
        <div class="ideas-head">
          <div>
            <h2>💡 선택 종목 투자 아이디어</h2>
            <p>가치·수익성·전망·모멘텀을 분리하고 시장 환경까지 함께 봅니다. 단일 매수점수가 아니라 확인해야 할 근거를 정리합니다.</p>
          </div>
          <button id="ideas-refresh" class="ideas-refresh" type="button">새로고침</button>
        </div>
        <div class="ideas-method">밸류/수익성: Yahoo Fundamentals · 전망: Yahoo 컨센서스 캐시 · 모멘텀: Yahoo Chart/한국 장마감 배치 · 시장환경: 경제지표 캐시</div>
        <div id="ideas-market" class="ideas-market"></div>
        <div id="ideas-leaders" class="ideas-leaders"></div>
        <div id="ideas-summary" class="ideas-summary">탭을 열면 선택 종목을 분석합니다.</div>
        <div id="ideas-grid" class="ideas-grid"><div class="ideas-empty">분석할 종목을 선택해 주세요.</div></div>
      </section>`;
    const macro = document.getElementById('macro-tab');
    if (macro) macro.insertAdjacentElement('beforebegin', tab);
    else document.getElementById('app')?.appendChild(tab);

    btn.addEventListener('click', () => {
      if (typeof window.switchTab === 'function') window.switchTab('ideas');
      loadIdeas();
    });
    tab.querySelector('#ideas-refresh')?.addEventListener('click', loadIdeas);

    const tags = document.getElementById('ticker-tags');
    if (tags && !tagObserver) {
      let timer = null;
      tagObserver = new MutationObserver(() => {
        if (document.querySelector('[data-tab="ideas"]')?.classList.contains('active')) {
          clearTimeout(timer);
          timer = setTimeout(loadIdeas, 120);
        }
      });
      tagObserver.observe(tags, { childList: true, subtree: true });
    }
  }

  function loadScreener() {
    if (!screenerPromise) {
      screenerPromise = fetch('/static/data/screener.json', { cache: 'force-cache' })
        .then((r) => r.ok ? r.json() : { stocks: [] })
        .catch(() => ({ stocks: [] }));
    }
    return screenerPromise;
  }

  function loadQuoteCache() {
    if (!quoteCachePromise) {
      quoteCachePromise = fetch('/static/data/valuation_cache.json', { cache: 'no-store' })
        .then((r) => r.ok ? r.json() : { quotes: {} })
        .catch(() => ({ quotes: {} }));
    }
    return quoteCachePromise;
  }

  function rsi14(values) {
    if (!Array.isArray(values) || values.length < 16) return null;
    const changes = [];
    for (let i = 1; i < values.length; i++) changes.push(values[i] - values[i - 1]);
    let gain = 0, loss = 0;
    for (let i = 0; i < 14; i++) {
      gain += Math.max(changes[i], 0);
      loss += Math.max(-changes[i], 0);
    }
    gain /= 14; loss /= 14;
    for (let i = 14; i < changes.length; i++) {
      gain = (gain * 13 + Math.max(changes[i], 0)) / 14;
      loss = (loss * 13 + Math.max(-changes[i], 0)) / 14;
    }
    if (loss === 0) return gain > 0 ? 100 : 50;
    return 100 - 100 / (1 + gain / loss);
  }

  function chartMomentum(compareStock) {
    const points = Array.isArray(compareStock?.data) ? compareStock.data : [];
    const values = points.map((p) => asNum(p.value)).filter((v) => v !== null).map((v) => 100 + v);
    if (values.length < 25) return null;
    const last = values.at(-1);
    const ret = (days) => values.length > days ? (last / values[values.length - 1 - days] - 1) * 100 : null;
    const avg = (n, end = values.length) => {
      if (end < n) return null;
      const slice = values.slice(end - n, end);
      return slice.reduce((a, b) => a + b, 0) / slice.length;
    };
    const ma20 = avg(20), ma60 = avg(60), ma120 = avg(120);
    const prev20 = avg(20, values.length - 1);
    const aligned = [ma20, ma60, ma120].every((v) => v !== null) && last > ma20 && ma20 > ma60 && ma60 > ma120;
    const cross20 = prev20 !== null && values.at(-2) <= prev20 && last > ma20;
    return { rsi: rsi14(values), ret20: ret(20), ret60: ret(60), aligned, cross20, source: 'Yahoo Chart · 최근 6개월 일봉' };
  }

  function calcMomentum(screenRow, compareStock) {
    if (screenRow) {
      return {
        rsi: asNum(screenRow.rsi14), ret20: asNum(screenRow.ret20), ret60: asNum(screenRow.ret60),
        aligned: !!screenRow.aligned, cross20: !!screenRow.cross20,
        source: `한국 ${screenRow.date || '-'} 장마감 배치`,
      };
    }
    return chartMomentum(compareStock) || { rsi: null, ret20: null, ret60: null, aligned: false, cross20: false, source: '모멘텀 데이터 없음' };
  }

  function outlook(stock, quote) {
    const trailing = asNum(stock.trailingPE);
    const forward = asNum(stock.forwardPE ?? quote?.forwardPE);
    if (forward === null || forward <= 0) return { label: '전망 데이터 없음', tone: 'neutral' };
    if (trailing !== null && trailing > 0) {
      const gap = (forward / trailing - 1) * 100;
      if (gap <= -12) return { label: 'FWD PER이 실적 PER보다 낮음', tone: 'good' };
      if (gap >= 15) return { label: 'FWD PER이 실적 PER보다 높음', tone: 'warn' };
    }
    return { label: '전망 중립', tone: 'neutral' };
  }

  function buildSignals(stock, screenRow, quote, compareStock) {
    const positives = [];
    const cautions = [];
    const positiveAxes = new Set();
    const cautionAxes = new Set();
    const addPositive = (axis, label) => { positives.push(label); positiveAxes.add(axis); };
    const addCaution = (axis, label) => { cautions.push(label); cautionAxes.add(axis); };
    const pe = asNum(stock.trailingPE), pbr = asNum(stock.pbr), roe = asNum(stock.roe), margin = asNum(stock.operatingMargin);
    const momentum = calcMomentum(screenRow, compareStock);
    const outlookInfo = outlook(stock, quote);

    if (pe !== null && pe > 0 && pe <= 15) addPositive('value', `PER ${pe.toFixed(1)}배 · 절대값 낮음`);
    else if (pe !== null && pe >= 40) addCaution('value', `PER ${pe.toFixed(1)}배 · 절대값 높음`);
    if (pbr !== null && pbr > 0 && pbr <= 2) addPositive('value', `PBR ${pbr.toFixed(1)}배`);
    if (roe !== null && roe >= 15) addPositive('profitability', `ROE ${roe.toFixed(1)}%`);
    else if (roe !== null && roe < 5) addCaution('profitability', `ROE ${roe.toFixed(1)}%`);
    if (margin !== null && margin >= 15) addPositive('profitability', `영업이익률 ${margin.toFixed(1)}%`);

    if (momentum.aligned) addPositive('momentum', '20·60·120일 정배열');
    else if (momentum.cross20) addPositive('momentum', '20일선 돌파');
    if (momentum.ret20 !== null && momentum.ret20 >= 8) addPositive('momentum', `20일 ${pct(momentum.ret20)}`);
    if (momentum.ret20 !== null && momentum.ret20 <= -12) addCaution('momentum', `20일 ${pct(momentum.ret20)}`);
    if (momentum.rsi !== null && momentum.rsi >= 70) addCaution('momentum', `RSI ${momentum.rsi.toFixed(1)} 과열`);
    if (momentum.rsi !== null && momentum.rsi <= 35) addPositive('momentum', `RSI ${momentum.rsi.toFixed(1)} 과매도권`);
    if (outlookInfo.tone === 'good') addPositive('outlook', outlookInfo.label);
    if (outlookInfo.tone === 'warn') addCaution('outlook', outlookInfo.label);

    const fields = ['trailingPE', 'pbr', 'roe', 'operatingMargin', 'forwardPE'];
    const complete = fields.filter((k) => asNum(stock[k] ?? (k === 'forwardPE' ? quote?.forwardPE : null)) !== null).length;
    const completeness = Math.round(complete / fields.length * 100);
    const coverage = `${complete}/${fields.length}`;

    let status = '근거 혼재', tone = 'neutral';
    if (positiveAxes.size >= 3 && cautionAxes.size === 0) { status = '긍정 근거 우세'; tone = 'good'; }
    if (cautionAxes.size >= 2) { status = '주의 근거 우세'; tone = 'warn'; }
    return { positives, cautions, momentum, completeness, coverage, status, tone };
  }

  function renderMarketContext(macro) {
    const el = document.getElementById('ideas-market');
    if (!el) return;
    if (!macro || !Array.isArray(macro.results)) {
      el.innerHTML = '<div class="ideas-market-empty">시장환경 데이터 없음</div>';
      return;
    }
    const rows = new Map(macro.results.map((x) => [x.original_symbol || x.symbol, x]));
    const summary = macro.summary || {};
    const level = summary.level || 'yellow';
    const label = level === 'green' ? '안정' : level === 'red' ? '위험' : '주의';
    const tone = level === 'green' ? 'good' : level === 'red' ? 'warn' : 'neutral';
    const vix = rows.get('^VIX');
    const curve = rows.get('T10Y2Y');
    const credit = rows.get('BAMLH0A0HYM2');
    const fed = rows.get('FEDFUNDS');
    const stale = Number(macro.staleCount || 0);
    const basis = summary.latestBasisDate || macro?.basis?.latest || '';

    el.innerHTML = `
      <div class="ideas-market-top">
        <div><span class="ideas-kicker">현재 시장환경</span><strong class="ideas-market-state ${tone}">${label}</strong></div>
        <span class="ideas-market-date">${stale ? `갱신 지연 ${stale}개` : '13개 지표 수집 성공'}${basis ? ` · 최근 원자료 ${esc(basis)}` : ''}</span>
      </div>
      <div class="ideas-market-metrics">
        <div><span>VIX</span><strong>${num(vix?.value, 1)}</strong></div>
        <div><span>10Y-2Y</span><strong>${num(curve?.value, 2)}%</strong></div>
        <div><span>하이일드</span><strong>${num(credit?.value, 2)}%</strong></div>
        <div><span>Fed Funds</span><strong>${num(fed?.value, 2)}%</strong></div>
      </div>
      <div class="ideas-market-text">${esc(summary.text || '시장환경 요약이 없습니다.')}</div>`;
  }

  function leader(items, extractor, mode = 'max') {
    const valid = items.map((item) => ({ item, value: asNum(extractor(item)) })).filter((x) => x.value !== null);
    if (!valid.length) return null;
    valid.sort((a, b) => mode === 'min' ? a.value - b.value : b.value - a.value);
    return valid[0];
  }

  function renderLeaders(stocks, screenMap, quotes, compareMap) {
    const el = document.getElementById('ideas-leaders');
    if (!el) return;
    if (!stocks.length) { el.innerHTML = ''; return; }

    const enriched = stocks.map((stock) => ({
      stock,
      quote: quotes[stock.ticker] || {},
      momentum: calcMomentum(screenMap.get(stock.ticker), compareMap.get(stock.ticker)),
      signal: buildSignals(stock, screenMap.get(stock.ticker), quotes[stock.ticker] || {}, compareMap.get(stock.ticker)),
    }));
    const fwd = leader(enriched, x => x.stock.forwardPE ?? x.quote.forwardPE, 'min');
    const roe = leader(enriched, x => x.stock.roe, 'max');
    const mom = leader(enriched, x => x.momentum.ret20, 'max');
    const quality = leader(enriched, x => x.signal.completeness, 'max');

    const cards = [
      fwd && ['낮은 FWD PER', fwd.item.stock.name || fwd.item.stock.ticker, `${num(fwd.value, 1)}x`],
      roe && ['높은 ROE', roe.item.stock.name || roe.item.stock.ticker, `${num(roe.value, 1)}%`],
      mom && ['강한 20일 모멘텀', mom.item.stock.name || mom.item.stock.ticker, pct(mom.value)],
      quality && ['필수 재무지표', quality.item.stock.name || quality.item.stock.ticker, quality.item.signal.coverage],
    ].filter(Boolean);

    el.innerHTML = cards.length ? `
      <div class="ideas-leaders-title">선택 종목 상대 비교 <span>낮음/높음 자체가 매수 신호는 아닙니다</span></div>
      <div class="ideas-leaders-grid">${cards.map(([label, name, value]) => `
        <div class="idea-leader"><span>${esc(label)}</span><strong>${esc(name)}</strong><em>${esc(value)}</em></div>`).join('')}
      </div>` : '';
  }

  function card(stock, screenRow, quote, compareStock) {
    const s = buildSignals(stock, screenRow, quote, compareStock);
    const analyst = quote?.averageAnalystRating ? esc(quote.averageAnalystRating) : '없음';
    const positiveHtml = s.positives.length ? s.positives.slice(0, 5).map((x) => `<span class="idea-chip good">${esc(x)}</span>`).join('') : '<span class="idea-chip neutral">강한 긍정 신호 없음</span>';
    const cautionHtml = s.cautions.length ? s.cautions.slice(0, 4).map((x) => `<span class="idea-chip warn">${esc(x)}</span>`).join('') : '<span class="idea-chip neutral">현재 확인한 지표에서 경고 조건 미충족</span>';
    return `
      <article class="idea-card">
        <div class="idea-card-top">
          <div><div class="idea-name">${esc(stock.name || stock.ticker)}</div><div class="idea-ticker">${esc(stock.ticker)}</div></div>
          <span class="idea-status ${s.tone}">${s.status}</span>
        </div>
        <div class="idea-axis-grid">
          <div><span>PER</span><strong>${num(stock.trailingPE)}x</strong></div>
          <div><span>PBR</span><strong>${num(stock.pbr)}x</strong></div>
          <div><span>ROE</span><strong>${num(stock.roe)}%</strong></div>
          <div><span>영업이익률</span><strong>${num(stock.operatingMargin)}%</strong></div>
          <div><span>FWD PER</span><strong>${num(stock.forwardPE ?? quote?.forwardPE)}x</strong></div>
          <div><span>20일 수익률</span><strong>${pct(s.momentum.ret20)}</strong></div>
        </div>
        <div class="idea-block"><div class="idea-block-title">볼 이유</div><div class="idea-chips">${positiveHtml}</div></div>
        <div class="idea-block"><div class="idea-block-title">확인할 위험</div><div class="idea-chips">${cautionHtml}</div></div>
        <div class="idea-foot"><span>애널리스트: ${analyst}</span><span>필수 재무지표 ${s.coverage} 제공</span><span>${esc(s.momentum.source)}</span></div>
      </article>`;
  }

  async function loadIdeas() {
    const seq = ++loadSeq;
    const tickers = selected().slice(0, 6);
    const grid = document.getElementById('ideas-grid');
    const summary = document.getElementById('ideas-summary');
    if (!grid || !summary) return;
    if (!tickers.length) {
      summary.textContent = '선택 종목 0개';
      document.getElementById('ideas-market').innerHTML = '';
      document.getElementById('ideas-leaders').innerHTML = '';
      grid.innerHTML = '<div class="ideas-empty">차트 또는 밸류에이션에서 종목을 먼저 선택해 주세요.</div>';
      return;
    }

    summary.textContent = '선택 종목 데이터를 확인하는 중...';
    grid.innerHTML = '<div class="ideas-loading"><div class="spinner"></div><span>투자 근거를 정리하는 중...</span></div>';

    try {
      const [valuation, screener, quoteCache, compare, macro] = await Promise.all([
        fetch(`/api/valuation?tickers=${encodeURIComponent(tickers.join(','))}`, { cache: 'no-store' }).then((r) => { if (!r.ok) throw new Error(`valuation ${r.status}`); return r.json(); }),
        loadScreener(), loadQuoteCache(),
        fetch(`/api/compare?tickers=${encodeURIComponent(tickers.join(','))}&period=6mo`, { cache: 'no-store' }).then((r) => r.ok ? r.json() : { stocks: [] }).catch(() => ({ stocks: [] })),
        fetch('/api/macro', { cache: 'no-store' }).then((r) => r.ok ? r.json() : null).catch(() => null),
      ]);
      if (seq !== loadSeq) return;
      const stocks = Array.isArray(valuation.stocks) ? valuation.stocks : [];
      const screenMap = new Map((screener.stocks || []).map((r) => [r.symbol, r]));
      const compareMap = new Map((compare.stocks || []).map((r) => [r.ticker, r]));
      const quotes = quoteCache.quotes || {};
      renderMarketContext(macro);
      renderLeaders(stocks, screenMap, quotes, compareMap);
      summary.textContent = `${stocks.length}개 종목 · 가치/수익성/전망/모멘텀 분리 평가 · 단일 매수점수 아님`;
      grid.innerHTML = stocks.map((stock) => card(stock, screenMap.get(stock.ticker), quotes[stock.ticker], compareMap.get(stock.ticker))).join('') || '<div class="ideas-empty">분석 가능한 데이터가 없습니다.</div>';
    } catch (err) {
      console.error('Ideas load failed', err);
      if (seq === loadSeq) {
        summary.textContent = '데이터를 불러오지 못했습니다.';
        grid.innerHTML = '<div class="ideas-empty">잠시 후 새로고침해 주세요.</div>';
      }
    }
  }

  function init() { installTab(); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true });
  else init();
})();
;

/* --- static/js/valuation_overview_v4.js --- */
(() => {
  'use strict';

  function applyDenseOverview() {
    try {
      if (typeof METRIC_CONFIG === 'undefined' || !METRIC_CONFIG.overview) return false;
      METRIC_CONFIG.overview.title = '밸류에이션 비교표';
      METRIC_CONFIG.overview.description = '종목을 행으로, 핵심 지표를 열로 배치해 여러 종목을 한눈에 비교합니다. 모바일에서는 표를 좌우로 밀어 확인하세요.';
      METRIC_CONFIG.overview.columns = [
        { key: 'forwardPE', label: 'FWD PER', format: 'number', color: true },
        { key: 'trailingPE', label: 'PER', format: 'number', color: true },
        { key: 'pbr', label: 'PBR', format: 'number', color: true },
        { key: 'psr', label: 'PSR', format: 'number', color: true },
        { key: 'evEbitda', label: 'EV/EBITDA', format: 'number', color: true },
        { key: 'roe', label: 'ROE(%)', format: 'percent', color: true },
        { key: 'operatingMargin', label: '영업이익률(%)', format: 'percent', color: true },
        { key: 'dividendYield', label: '배당률(%)', format: 'percent', color: true },
      ];
      METRIC_CONFIG.overview.barKey = 'forwardPE';
      METRIC_CONFIG.overview.barLabel = 'FWD PER (전망)';
      METRIC_CONFIG.overview.sortKey = 'forwardPE';
      if (typeof currentMetric !== 'undefined' && currentMetric === 'overview' && typeof renderPerTable === 'function') {
        renderPerTable();
      }
      return true;
    } catch (error) {
      console.warn('Dense valuation overview unavailable:', error);
      return false;
    }
  }

  if (!applyDenseOverview()) {
    let attempts = 0;
    const timer = setInterval(() => {
      attempts += 1;
      if (applyDenseOverview() || attempts >= 20) clearInterval(timer);
    }, 150);
  }
})();
;

/* --- static/js/revision_radar.js --- */
(() => {
  'use strict';

  let cachePromise = null;
  let currentPeriod = '0y';

  const esc = (value) => String(value ?? '')
    .replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;').replaceAll("'", '&#39;');

  const asNum = (value) => {
    if (value === null || value === undefined || value === '') return null;
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
  };

  const pct = (value, digits = 1) => {
    const n = asNum(value);
    if (n === null) return '-';
    return `${n > 0 ? '+' : ''}${n.toFixed(digits)}%`;
  };

  function changePct(current, previous) {
    const a = asNum(current);
    const b = asNum(previous);
    // Percentage revisions are only comparable while both estimates are positive.
    // Crossing zero (loss -> profit or vice versa) makes a ratio misleading.
    if (a === null || b === null || a <= 0 || b <= 0) return null;
    return (a / b - 1) * 100;
  }

  function marketOf(symbol) {
    return /\.(KS|KQ)$/.test(symbol) ? 'KR' : 'US';
  }

  function classify(eps30, balance) {
    if (eps30 !== null && eps30 >= 3 && balance > 0) return { key: 'strong', label: '강한 상향' };
    if (eps30 !== null && eps30 > 0 && balance >= 0) return { key: 'up', label: '상향' };
    if (eps30 !== null && eps30 <= -3 && balance < 0) return { key: 'down', label: '하향 주의' };
    return { key: 'neutral', label: '중립' };
  }

  function enrich(symbol, quote, localNames) {
    const row = (quote.periods || {})[currentPeriod] || {};
    const earnings = row.earnings || {};
    const trend = row.epsTrend || {};
    const revisions = row.revisions || {};
    const revenue = row.revenue || {};
    const current = asNum(trend.current ?? earnings.avg);
    const eps7 = changePct(current, trend['7daysAgo']);
    const eps30 = changePct(current, trend['30daysAgo']);
    const eps90 = changePct(current, trend['90daysAgo']);
    const up30 = asNum(revisions.up30) || 0;
    const down30 = asNum(revisions.down30) || 0;
    const balance = up30 - down30;
    const analysts = asNum(earnings.analysts);
    const signal = classify(eps30, balance);
    const accelerating = eps7 !== null && eps30 !== null && eps7 > 0.3 && eps30 > 0;

    return {
      symbol,
      name: localNames.get(symbol) || quote.name || symbol,
      market: marketOf(symbol),
      endDate: row.endDate || '-',
      eps30,
      eps90,
      eps7,
      up30,
      down30,
      balance,
      analysts,
      epsGrowth: asNum(earnings.growth) === null ? null : asNum(earnings.growth) * 100,
      revenueGrowth: asNum(revenue.growth) === null ? null : asNum(revenue.growth) * 100,
      signal,
      accelerating,
    };
  }

  function signalRank(row) {
    return row.signal.key === 'strong' ? 3 : row.signal.key === 'up' ? 2 : row.signal.key === 'neutral' ? 1 : 0;
  }

  function sortRows(rows) {
    return [...rows].sort((a, b) => {
      const signalDiff = signalRank(b) - signalRank(a);
      if (signalDiff) return signalDiff;
      const epsDiff = (b.eps30 ?? -Infinity) - (a.eps30 ?? -Infinity);
      if (epsDiff) return epsDiff;
      return b.balance - a.balance;
    });
  }

  function candidateRows(rows, market) {
    const all = sortRows(rows.filter((row) => row.market === market && row.eps30 !== null && (row.analysts || 0) >= 2));
    const positives = all.filter((row) => row.signal.key === 'strong' || row.signal.key === 'up');
    return (positives.length ? positives : all).slice(0, 6);
  }

  function card(row) {
    const balanceText = `${Math.round(row.up30)}↑ / ${Math.round(row.down30)}↓`;
    return `
      <article class="revision-card" data-revision-signal="${row.signal.key}">
        <div class="revision-card-top">
          <div>
            <strong class="revision-name">${esc(row.name)}</strong>
            <span class="revision-symbol">${esc(row.symbol)}</span>
          </div>
          <span class="revision-badge ${row.signal.key}">${row.signal.label}</span>
        </div>
        <div class="revision-main">
          <div><span>EPS 30일 변화</span><strong class="${(row.eps30 || 0) >= 0 ? 'revision-up' : 'revision-down'}">${pct(row.eps30)}</strong></div>
          <div><span>EPS 90일 변화</span><strong>${pct(row.eps90)}</strong></div>
          <div><span>30일 의견</span><strong>${balanceText}</strong></div>
          <div><span>EPS 성장률</span><strong>${pct(row.epsGrowth)}</strong></div>
        </div>
        <div class="revision-foot">
          <span>${row.accelerating ? '⚡ 최근 7일 상향 가속 · ' : ''}매출 성장 ${pct(row.revenueGrowth)} · ${Math.round(row.analysts || 0)}명 · ${esc(row.endDate)}</span>
          <button class="revision-analyze" data-symbol="${esc(row.symbol)}" data-name="${esc(row.name)}" type="button">분석하기</button>
        </div>
      </article>`;
  }

  function section(title, rows, emptyText) {
    return `
      <section class="revision-market-block">
        <div class="revision-market-title">${title}</div>
        ${rows.length
          ? `<div class="revision-grid">${rows.map(card).join('')}</div>`
          : `<div class="revision-empty">${emptyText}</div>`}
      </section>`;
  }

  function bindActions(root) {
    root.querySelectorAll('.revision-analyze').forEach((button) => {
      button.addEventListener('click', () => {
        const symbol = button.dataset.symbol;
        const name = button.dataset.name;
        if (typeof window.addGlobalTicker === 'function') window.addGlobalTicker(symbol, name);
        const ideasButton = document.querySelector('.tab-nav [data-tab="ideas"]');
        if (ideasButton) ideasButton.click();
        else if (typeof window.switchTab === 'function') window.switchTab('fwdper');
        window.scrollTo({ top: 0, behavior: 'smooth' });
      });
    });
  }

  async function loadSource() {
    if (!cachePromise) {
      cachePromise = Promise.all([
        fetch('/static/data/consensus_cache.json', { cache: 'no-store' }).then((r) => {
          if (!r.ok) throw new Error(`consensus HTTP ${r.status}`);
          return r.json();
        }),
        fetch('/static/data/screener.json', { cache: 'force-cache' }).then((r) => r.ok ? r.json() : { stocks: [] }).catch(() => ({ stocks: [] })),
      ]);
    }
    return cachePromise;
  }

  async function render() {
    const root = document.getElementById('revision-radar-body');
    if (!root) return;
    root.innerHTML = '<div class="revision-loading"><div class="spinner"></div><span>실적 컨센서스를 정리하는 중...</span></div>';

    try {
      const [consensus, screener] = await loadSource();
      const quotes = consensus.quotes || {};
      const localNames = new Map((screener.stocks || []).map((row) => [row.symbol, row.name]));
      const rows = Object.entries(quotes)
        .map(([symbol, quote]) => enrich(symbol, quote, localNames))
        .filter((row) => row.eps30 !== null);

      const strong = rows.filter((row) => row.signal.key === 'strong').length;
      const up = rows.filter((row) => row.signal.key === 'up').length;
      const down = rows.filter((row) => row.signal.key === 'down').length;
      const kr = candidateRows(rows, 'KR');
      const us = candidateRows(rows, 'US');

      root.innerHTML = `
        <div class="revision-summary">
          <div><span>강한 상향</span><strong>${strong}</strong></div>
          <div><span>상향</span><strong>${up}</strong></div>
          <div><span>하향 주의</span><strong>${down}</strong></div>
          <div><span>분석 가능</span><strong>${rows.length}</strong></div>
        </div>
        <div class="revision-method">정렬 기준: 강한 상향 → EPS 30일 변화율 → 상향·하향 의견 차이. 적자↔흑자처럼 EPS가 0을 가로지르는 구간은 왜곡을 막기 위해 순위에서 제외합니다. 숨은 매수점수는 사용하지 않습니다.</div>
        ${section('🇰🇷 한국 상향 후보', kr, '현재 조건에서 한국 상향 후보가 없습니다.')}
        ${section('🇺🇸 미국 상향 후보', us, '현재 조건에서 미국 상향 후보가 없습니다.')}
        <div class="revision-source">Yahoo Finance earningsTrend · 현재 컨센서스 캐시 ${Object.keys(quotes).length}종목 · ${esc(String(consensus.generatedAt || '').slice(0, 10))} 갱신</div>`;
      bindActions(root);
    } catch (error) {
      console.error('Revision radar failed:', error);
      root.innerHTML = '<div class="revision-empty">실적 컨센서스 데이터를 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.</div>';
    }
  }

  function install() {
    if (document.getElementById('revision-tab')) return;
    const tab = document.createElement('div');
    tab.id = 'revision-tab';
    tab.className = 'tab-content';
    tab.innerHTML = `
      <section class="revision-section">
        <div class="revision-head">
          <div>
            <h2>🚀 실적 추정치 상향 레이더</h2>
            <p>애널리스트 EPS 추정치가 실제로 올라가는 종목을 자동으로 먼저 보여줍니다.</p>
          </div>
          <div class="revision-period" role="group" aria-label="컨센서스 기간">
            <button type="button" class="revision-period-btn active" data-revision-period="0y">올해</button>
            <button type="button" class="revision-period-btn" data-revision-period="+1y">내년</button>
          </div>
        </div>
        <div id="revision-radar-body"><div class="revision-empty">실적 상향 탭을 열면 데이터를 불러옵니다.</div></div>
      </section>`;

    const screener = document.getElementById('screener-tab');
    if (screener) screener.insertAdjacentElement('afterend', tab);
    else document.getElementById('app')?.appendChild(tab);

    tab.querySelectorAll('[data-revision-period]').forEach((button) => {
      button.addEventListener('click', () => {
        tab.querySelectorAll('[data-revision-period]').forEach((item) => item.classList.remove('active'));
        button.classList.add('active');
        currentPeriod = button.dataset.revisionPeriod;
        render();
      });
    });
  }

  window.__loadRevisionRadar = render;

  function init() {
    install();
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init, { once: true });
  else init();
})();
;

